        static readonly string[] CompatLabel = { "Proton compatibility mode", "Proton-Kompatibilit\u00e4tsmodus", "Mode de compatibilit\u00e9 Proton", "Modalit\u00e0 di compatibilit\u00e0 Proton", "Modo de compatibilidad con Proton", "Proton\u4e92\u63db\u30e2\u30fc\u30c9", "Proton \ud638\ud658 \ubaa8\ub4dc", "Proton \u76f8\u5bb9\u6a21\u5f0f" };
        static readonly string[] CompatHelp = { "For SteamOS / Steam Deck. On: FFX.exe and FFX-2.exe are replaced by their 60 fps builds, so Steam and Proton start the games under their own file names. The originals are backed up first in backup_original (CRC checked). Off: the originals are restored. Takes effect when saved.", "F\u00fcr SteamOS / Steam Deck. Ein: FFX.exe und FFX-2.exe werden durch ihre 60-fps-Fassungen ersetzt, damit Steam und Proton die Spiele unter ihren eigenen Dateinamen starten. Die Originale werden vorher in backup_original gesichert (CRC gepr\u00fcft). Aus: die Originale werden wiederhergestellt. Gilt ab dem Speichern.", "Pour SteamOS / Steam Deck. Activ\u00e9 : FFX.exe et FFX-2.exe sont remplac\u00e9s par leurs versions 60 fps, afin que Steam et Proton lancent les jeux sous leurs propres noms de fichier. Les originaux sont d'abord sauvegard\u00e9s dans backup_original (CRC v\u00e9rifi\u00e9). D\u00e9sactiv\u00e9 : les originaux sont restaur\u00e9s. Prend effet \u00e0 l'enregistrement.", "Per SteamOS / Steam Deck. Attiva: FFX.exe e FFX-2.exe vengono sostituiti dalle loro versioni a 60 fps, cos\u00ec Steam e Proton avviano i giochi con i loro nomi di file. Gli originali vengono prima salvati in backup_original (CRC verificato). Disattiva: gli originali vengono ripristinati. Ha effetto al salvataggio.", "Para SteamOS / Steam Deck. Activado: FFX.exe y FFX-2.exe se sustituyen por sus versiones de 60 fps, para que Steam y Proton inicien los juegos con sus propios nombres de archivo. Antes se guardan los originales en backup_original (CRC comprobado). Desactivado: se restauran los originales. Se aplica al guardar.", "SteamOS / Steam Deck \u5411\u3051\u3002\u30aa\u30f3\uff1aFFX.exe \u3068 FFX-2.exe \u3092 60 fps \u7248\u306b\u7f6e\u304d\u63db\u3048\u3001Steam \u3068 Proton \u304c\u5143\u306e\u30d5\u30a1\u30a4\u30eb\u540d\u3067\u30b2\u30fc\u30e0\u3092\u8d77\u52d5\u3067\u304d\u308b\u3088\u3046\u306b\u3057\u307e\u3059\u3002\u30aa\u30ea\u30b8\u30ca\u30eb\u306f\u5148\u306b backup_original \u306b\u4fdd\u5b58\u3055\u308c\u307e\u3059\uff08CRC \u78ba\u8a8d\u6e08\u307f\uff09\u3002\u30aa\u30d5\uff1a\u30aa\u30ea\u30b8\u30ca\u30eb\u3092\u5143\u306b\u623b\u3057\u307e\u3059\u3002\u4fdd\u5b58\u3057\u305f\u6642\u70b9\u3067\u53cd\u6620\u3055\u308c\u307e\u3059\u3002", "SteamOS / Steam Deck\uc6a9. \ucf1c\uae30: FFX.exe\uc640 FFX-2.exe\ub97c 60 fps \ubc84\uc804\uc73c\ub85c \ubc14\uafb8\uc5b4 Steam\uacfc Proton\uc774 \uc6d0\ub798 \ud30c\uc77c \uc774\ub984\uc73c\ub85c \uac8c\uc784\uc744 \uc2e4\ud589\ud558\uac8c \ud569\ub2c8\ub2e4. \uc6d0\ubcf8\uc740 \uba3c\uc800 backup_original\uc5d0 \ubc31\uc5c5\ub429\ub2c8\ub2e4(CRC \ud655\uc778). \ub044\uae30: \uc6d0\ubcf8\uc744 \ubcf5\uc6d0\ud569\ub2c8\ub2e4. \uc800\uc7a5\ud558\uba74 \uc801\uc6a9\ub429\ub2c8\ub2e4.", "\u9069\u7528\u65bc SteamOS / Steam Deck\u3002\u958b\u555f\uff1a\u5c07 FFX.exe \u8207 FFX-2.exe \u66ff\u63db\u70ba 60 fps \u7248\u672c\uff0c\u8b93 Steam \u8207 Proton \u4ee5\u539f\u672c\u7684\u6a94\u540d\u555f\u52d5\u904a\u6232\u3002\u539f\u59cb\u6a94\u6848\u6703\u5148\u5099\u4efd\u5230 backup_original\uff08\u5df2\u6aa2\u67e5 CRC\uff09\u3002\u95dc\u9589\uff1a\u9084\u539f\u539f\u59cb\u6a94\u6848\u3002\u5132\u5b58\u5f8c\u751f\u6548\u3002" };
        static readonly string[] TabControls = { "Controls", "Steuerung", "Commandes", "Controlli", "Controles", "\u64cd\u4f5c\u8a2d\u5b9a", "\uc870\uc791", "\u64cd\u4f5c" };
        static readonly string[] TabAdvanced = { "Advanced", "Erweitert", "Avanc\u00e9", "Avanzate", "Avanzado", "\u8a73\u7d30\u8a2d\u5b9a", "\uace0\uae09", "\u9032\u968e" };
